INSERT INTO product_translations (product_id, lang, data) VALUES ('pre-assembled', 'cs', '{"name": "Star‑A — Plně smontováno", "description": " - Plně smontováno a otestováno. Vložte 3× 18650 baterie, přepněte páčku a sledujte, jak spadnou čelisti. Vyberte si UFO nebo Mushroom — čtyři barevné provedení. Není vyžadována žádná montáž.", "category": "Lampa"}');
