INSERT INTO product_translations (product_id, lang, data) VALUES ('ufo-kit-spaceblue', 'cs', '{"name": "Star‑A — DIY stavebnice", "description": "Space Blue - DIY stavebnice. Obsahuje VŠECHNY 3D tištěné díly a hardware, které potřebujete k výrobě vlastní lampy. *baterie 3 × 18650 nejsou součástí! (objednejte zvlášť)", "category": "Stavebnice", "label": "UFO — SpaceBlues"}');
