INSERT INTO product_translations (product_id, lang, data) VALUES ('star-a-kit', 'cs', '{"name": "Star‑A — Stavebnice pro vlastní sestavení", "description": "Předtištěné díly a kompletní elektronická stavebnice. Sestavte za přibližně 90 minut s dospělou osobou. Není potřeba 3D tiskárna, pájení ani shánění součástek. Součástí je podrobný ilustrovaný návod krok za krokem. Vyberte si UFO nebo Mushroom — čtyři barevná provedení.", "category": "Stavebnice"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('complete-assembly-kit', 'cs', '{"name": "Kompletní montážní sada", "description": "Předtištěné díly a kompletní elektronická stavebnice. Sestavte za přibližně 90 minut s dospělou osobou. Není potřeba 3D tiskárna ani pájení. Součástí je podrobný ilustrovaný návod krok za krokem.", "category": "Stavebnice"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('electronics-bundle', 'cs', '{"name": "Elektronický balíček", "description": "Veškerá elektronika předem zapojená a připravená k montáži — stejnosměrný motor s Faston konektory, 3polohová páčková spínač, hlavní vypínač, 3W LED hlava, držák 3× 18650 baterií, barevně odlišená kabeláž a Wago svorkovnice. Tištěné díly nejsou součástí.", "category": "Stavebnice"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('printed-parts-ufo', 'cs', '{"name": "Sada tištěných dílů pro UFO", "description": "Všechny konstrukční díly pro model UFO, profesionálně vytištěné v PLA+. Obsahuje základnu, tři trubkové sekce, převodovou skříň, držák motoru a talířovou hlavu UFO. Přesné tolerance, zaručený fit.", "category": "Díly"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('printed-parts-mushroom', 'cs', '{"name": "Sada tištěných dílů pro Mushroom", "description": "Všechny konstrukční díly pro model Mushroom, profesionálně vytištěné v PLA+. Obsahuje základnu, tři trubkové sekce, převodovou skříň, držák motoru a klobouk houby. Přesné tolerance, zaručený fit.", "category": "Díly"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('batteries-3pack', 'cs', '{"name": "3× chráněné 18650 baterie", "description": "Chráněné lithiové články 18650 — přesně to, co Star‑A potřebuje. Tři články v balení. Ochranný obvod zabraňuje přebití, hlubokému vybití a zkratu.", "category": "Příslušenství"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('18650-charger', 'cs', '{"name": "Nabíječka pro 18650 baterie", "description": "Kompaktní 4-místná nabíječka pro články 18650. Bezpečné nabíjení přes noc. Automatické vypnutí po plném nabití.", "category": "Příslušenství"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-led', 'cs', '{"name": "3W Star LED (náhradní)", "description": "Teplá bílá 3W náhradní LED hlava, předem zapojená s kabely připravenými pro Wago. Výměna bez nářadí. Pasuje na modely UFO i Mushroom.", "category": "Příslušenství"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-motor', 'cs', '{"name": "Stejnosměrný motor (náhrada)", "description": "Náhradní stejnosměrný motor pro přímou výměnu. Osazen Faston konektory — bez pájení, bez nářadí.", "category": "Příslušenství"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-lever-switch', 'cs', '{"name": "3polohová páčková spínač", "description": "Ovládání páčkou Nahoru–Vypnuto–Dolů. Předem zapojeno a připraveno k montáži. Páčka, která zajišťuje zvedání, zastavení a stahování sloupu.", "category": "Příslušenství"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-push-switch', 'cs', '{"name": "Hlavní vypínač (LED)", "description": "Kulatý tlačítkový spínač s integrovanou LED indikací. 2A 250V. Předem zapojen, zasuňte a zacvakněte.", "category": "Příslušenství"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-battery-holder', 'cs', '{"name": "Držák 3× 18650 baterií", "description": "Chráněný držák baterií s výstupními kabely připravenými pro Wago. Pojme tři články 18650. Přímá náhrada do základny Star‑A.", "category": "Příslušenství"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('wago-terminals', 'cs', '{"name": "Wago 221 svorkovnice (10 ks)", "description": "Beznástrojové zasouvací spoje. Směs 2-cestných (221-412) a 3-cestných (221-413) svorkovnic — stejné, které se používají v každé stavebnici Star‑A.", "category": "Příslušenství"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('led-driver', 'cs', '{"name": "Mean Well LDD-700L LED driver", "description": "700mA konstantní proudový DC-DC step-down LED driver. Napájí 3W LED hlavu z bateriového bloku 18650.", "category": "Příslušenství"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('mushroom-spare-red', 'cs', '{"name": "Mushroom červený klobouk a bílý stonek", "description": "Rozšiřte nebo vyměňte vršek své lampy Star-A. Díky našemu univerzálnímu klipovacímu systému můžete snadno vyměnit vršek a vytvořit nový ''vzhled'' vaší lampy Dornori", "category": "Příslušenství", "label": "Mushroom KLOBOUK/STONEK červený/bílý"}');
