INSERT INTO product_translations (product_id, lang, data) VALUES ('pre-assembled', 'de', '{"name": "Star‑A — Fully Built", "description": "Fully assembled and tested. Load 3× 18650 batteries, flip the lever, watch jaws drop. Choose UFO or Mushroom — four colourways each. No build required.", "category": "Lamp", "shipsFrom": "Dornori Versand", "soldBy": "Dornori", "returns": "30 Tage Rückgabe oder Ersatz", "specs": [{"title": "Merkmale & Spezifikationen", "rows": [["Höhe (eingefahren)", "70 cm"], ["Höhe (ausgefahren)", "190 cm"], ["Lichtquelle", "3W warmweißes LED"], ["Stromversorgung", "3× 18650 Akkus (nicht enthalten)"], ["Motor", "DC-Getriebemotor, 3–6V"], ["Ausfahrmechanismus", "3-teiliges Teleskopsystem mit Zahnradantrieb"]]}, {"title": "Materialien & Pflege", "rows": [["Gehäusematerial", "PLA+ (3D-gedruckt)"], ["Oberfläche", "Pulverbeschichtete Aluminiumakzente"], ["Schirmmaterial", "PC/ABS"], ["Reinigung", "Mit trockenem oder leicht feuchtem Tuch abwischen"], ["UV-Beständigkeit", "Mäßig — direktes Sonnenlicht vermeiden"]]}, {"title": "Produktdetails", "rows": [["Modell", "Star‑A"], ["Varianten", "UFO / Pilz, je 4 Farbvarianten"], ["Montage erforderlich", "Nein — vollständig gebaut und getestet"], ["Gewicht", "1,8 kg"], ["Verpackungsmaße", "75 × 15 × 15 cm"]]}, {"title": "Garantie & Support", "rows": [["Garantiezeitraum", "2 Jahre ab Kaufdatum"], ["Support", "support@dornori.com"], ["Rückgaberecht", "30 Tage Rückgabe oder Ersatz — keine Fragen gestellt"], ["Ersatzteile", "Einzeln im Shop erhältlich"]]}]}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('star-a-kit', 'de', '{"name": "Star‑A — Build-It Kit", "description": "Pre-printed parts and a complete electronics kit. Build in around 90 minutes with an adult. No 3D printer, no soldering, no component hunting. Step-by-step illustrated guide included. Choose UFO or Mushroom — four colourways each.", "category": "Kit", "shipsFrom": "Dornori Versand", "soldBy": "Dornori", "returns": "30 Tage Rückgabe oder Ersatz", "specs": [{"title": "Kit-Inhalt", "rows": [["Gedruckte Teile", "Vollständiger Satz — Basis, Rohre, Getriebegehäuse, Kopf"], ["Elektronik", "Motor, Schalter, LED, Batteriehalter, Kabelsatz"], ["Verbinder", "Wago 221 Hebelklemmen"], ["Anleitung", "Schritt-für-Schritt-Bildanleitung"]]}, {"title": "Bauinformationen", "rows": [["Bauzeit", "~90 Minuten"], ["Benötigtes Werkzeug", "Keins"], ["Löten erforderlich", "Nein"], ["3D-Drucker erforderlich", "Nein"], ["Empfohlenes Alter", "14+ (Erwachsenenaufsicht für jüngere Bauende)"]]}, {"title": "Garantie & Support", "rows": [["Garantiezeitraum", "2 Jahre ab Kaufdatum"], ["Support", "support@dornori.com"], ["Rückgaberecht", "30 Tage Rückgabe oder Ersatz"]]}]}');
