INSERT INTO product_translations (product_id, lang, data) VALUES ('star-a-kit', 'en', '{"sku": "STA-A-BLD-GEN-STD", "name": "Star‑A — Build-It Kit", "description": "Pre-printed parts and a complete electronics kit. Build in around 90 minutes with an adult. No 3D printer, no soldering, no component hunting. Step-by-step illustrated guide included. Choose UFO or Mushroom — four colourways each.", "category": "Kit"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('complete-assembly-kit', 'en', '{"sku": "STA-A-BLD-GEN-STD", "name": "Complete Assembly Kit", "description": "Pre-printed parts and a complete electronics kit. Build in around 90 minutes with an adult. No 3D printer, no soldering. Step-by-step illustrated guide included.", "category": "Kit"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('electronics-bundle', 'en', '{"sku": "STA-A-ELE-GEN-STD", "name": "Electronics Bundle", "description": "All electronics pre-wired and ready to assemble — DC motor with Faston connectors, 3-position lever switch, main power switch, 3W LED lamp head, 3× 18650 battery holder, colour-coded wiring harness, and Wago lever terminals. No printed parts included.", "category": "Kit"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('printed-parts-ufo', 'en', '{"sku": "STA-A-PRT-UFO-STD", "name": "UFO Printed Parts Set", "description": "All structural parts for the UFO model, professionally printed in PLA+. Includes base body, three tube sections, gear housing, motor bracket, and UFO saucer head. Tight tolerances, guaranteed fit.", "category": "Parts"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('printed-parts-mushroom', 'en', '{"sku": "STA-A-PRT-MUS-STD", "name": "Mushroom Printed Parts Set", "description": "All structural parts for the Mushroom model, professionally printed in PLA+. Includes base body, three tube sections, gear housing, motor bracket, and mushroom cap. Tight tolerances, guaranteed fit.", "category": "Parts"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('batteries-3pack', 'en', '{"sku": "STA-A-ACC-BAT-3PK", "name": "3× Protected 18650 Batteries", "description": "Protected 18650 lithium cells — exactly what the Star‑A needs. Three cells per pack. Protected circuit prevents overcharge, over-discharge, and short circuit.", "category": "Accessories"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('18650-charger', 'en', '{"sku": "STA-A-ACC-CHG-186", "name": "18650 Battery Charger", "description": "Compact 4-slot charger for 18650 cells. Charges safely overnight. Automatic shutoff when full.", "category": "Accessories"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-led', 'en', '{"sku": "STA-A-ACC-LED-3W", "name": "3W Star LED (Spare)", "description": "Warm-white 3W replacement LED lamp head, pre-wired with Wago-ready cables. Tool-free swap. Fits both UFO and Mushroom models.", "category": "Accessories"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-motor', 'en', '{"sku": "STA-A-ACC-MTR-DC", "name": "DC Motor (Replacement)", "description": "Drop-in replacement DC motor. Pre-fitted with Faston connectors — no soldering, no tools needed.", "category": "Accessories"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-lever-switch', 'en', '{"sku": "STA-A-ACC-SWL-3POS", "name": "3-Position Lever Switch", "description": "Up–Off–Down lever control. Pre-wired and ready to fit. The lever that makes the pole rise, stop, and retract.", "category": "Accessories"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-push-switch', 'en', '{"sku": "STA-A-ACC-SWP-LED", "name": "Main Power Switch (LED)", "description": "Round push switch with integrated LED indicator. 2A 250V. Pre-wired, push-to-fit.", "category": "Accessories"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-battery-holder', 'en', '{"sku": "STA-A-ACC-HLD-3X", "name": "3× 18650 Battery Holder", "description": "Protected battery holder with Wago-ready output cables. Holds three 18650 cells. Drop-in replacement for the Star‑A base.", "category": "Accessories"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('wago-terminals', 'en', '{"sku": "STA-A-ACC-WAG-10PK", "name": "Wago 221 Lever Terminals (10-pack)", "description": "Tool-free push-in wire connections. Mix of 2-way (221-412) and 3-way (221-413) terminals — the same ones used in every Star‑A kit.", "category": "Accessories"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('led-driver', 'en', '{"sku": "STA-A-ACC-DRV-700", "name": "Mean Well LDD-700L LED Driver", "description": "700mA constant-current DC-DC step-down LED driver. Powers the 3W LED head from the 18650 battery pack.", "category": "Accessories"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('mushroom-spare-red', 'en', '{"sku": "STA-A-ACC-MUS-RED", "name": "Mushroom Red Cap and White Stem", "description": "Extend or replace your Star-A lamp top. With our universal clip-on system you can easily replace the top and create a new ''look'' for your Dornori Light", "category": "Accessories", "label": "Mushroom CAP/STEM red/white"}');
