INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-lever-switch', 'it', '{"name": "3-Position Lever Switch", "description": "Up–Off–Down lever control. Pre-wired and ready to fit. The lever that makes the pole rise, stop, and retract.", "category": "Accessories", "shipsFrom": "Spedizione Dornori", "soldBy": "Dornori", "returns": "Restituzione o sostituzione entro 30 giorni", "specs": [{"title": "Compatibilità", "rows": [["Compatibile con", "Star‑A (tutte le varianti)"]]}, {"title": "Garanzia e Supporto", "rows": [["Periodo di garanzia", "1 anno"], ["Supporto", "support@dornori.com"], ["Politica di reso", "Reso o sostituzione entro 30 giorni"]]}]}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-push-switch', 'it', '{"name": "Main Power Switch (LED)", "description": "Round push switch with integrated LED indicator. 2A 250V. Pre-wired, push-to-fit.", "category": "Accessories", "shipsFrom": "Spedizione Dornori", "soldBy": "Dornori", "returns": "Restituzione o sostituzione entro 30 giorni", "specs": [{"title": "Compatibilità", "rows": [["Compatibile con", "Star‑A (tutte le varianti)"]]}, {"title": "Garanzia e Supporto", "rows": [["Periodo di garanzia", "1 anno"], ["Supporto", "support@dornori.com"], ["Politica di reso", "Reso o sostituzione entro 30 giorni"]]}]}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-battery-holder', 'it', '{"name": "3× 18650 Battery Holder", "description": "Protected battery holder with Wago-ready output cables. Holds three 18650 cells. Drop-in replacement for the Star‑A base.", "category": "Accessories", "shipsFrom": "Spedizione Dornori", "soldBy": "Dornori", "returns": "Restituzione o sostituzione entro 30 giorni", "specs": [{"title": "Compatibilità", "rows": [["Compatibile con", "Star‑A (tutte le varianti)"]]}, {"title": "Garanzia e Supporto", "rows": [["Periodo di garanzia", "1 anno"], ["Supporto", "support@dornori.com"], ["Politica di reso", "Reso o sostituzione entro 30 giorni"]]}]}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('wago-terminals', 'it', '{"name": "Wago 221 Lever Terminals (10-pack)", "description": "Tool-free push-in wire connections. Mix of 2-way (221-412) and 3-way (221-413) terminals — the same ones used in every Star‑A kit.", "category": "Accessories", "shipsFrom": "Spedizione Dornori", "soldBy": "Dornori", "returns": "Restituzione o sostituzione entro 30 giorni", "specs": [{"title": "Compatibilità", "rows": [["Compatibile con", "Star‑A (tutte le varianti)"]]}, {"title": "Garanzia e Supporto", "rows": [["Periodo di garanzia", "1 anno"], ["Supporto", "support@dornori.com"], ["Politica di reso", "Reso o sostituzione entro 30 giorni"]]}]}');
