INSERT INTO product_translations (product_id, lang, data) VALUES ('star-a-kit', 'nl', '{"name": "Star‑A — Bouw-het-zelf-bouwpakket", "description": "Voorgeprinte onderdelen en een compleet elektronica-bouwpakket. Bouw het in ongeveer 90 minuten met een volwassene. Geen 3D-printer, geen soldeerwerk, geen onderdelenjacht. Stapsgewijze geïllustreerde handleiding inbegrepen. Kies uit UFO of Mushroom — vier kleurstellingen per model.", "category": "Bouwpakket"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('complete-assembly-kit', 'nl', '{"name": "Compleet montagepakket", "description": "Voorgeprinte onderdelen en een compleet elektronica-bouwpakket. Bouw het in ongeveer 90 minuten met een volwassene. Geen 3D-printer, geen soldeerwerk. Stapsgewijze geïllustreerde handleiding inbegrepen.", "category": "Bouwpakket"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('electronics-bundle', 'nl', '{"name": "Elektronicabundel", "description": "Alle elektronica voorbedraad en klaar voor montage — gelijkstroommotor met Faston-connectoren, 3-stands hendelschakelaar, hoofdschakelaar, 3W LED-lampkop, 3× 18650-batterijhouder, kleurgecodeerde bedrading en Wago-klemmen. Geen geprinte onderdelen inbegrepen.", "category": "Bouwpakket"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('printed-parts-ufo', 'nl', '{"name": "UFO geprinte onderdelenset", "description": "Alle structurele onderdelen voor het UFO-model, professioneel geprint in PLA+. Inclusief basislichaam, drie buisonderdelen, tandwielbehuizing, motorbeugel en UFO-schotelkop. Strakke toleranties, gegarandeerde pasvorm.", "category": "Onderdelen"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('printed-parts-mushroom', 'nl', '{"name": "Mushroom geprinte onderdelenset", "description": "Alle structurele onderdelen voor het Mushroom-model, professioneel geprint in PLA+. Inclusief basislichaam, drie buisonderdelen, tandwielbehuizing, motorbeugel en paddenstoelhoed. Strakke toleranties, gegarandeerde pasvorm.", "category": "Onderdelen"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('batteries-3pack', 'nl', '{"name": "3× Beschermde 18650-batterijen", "description": "Beschermde 18650-lithiumcellen — precies wat de Star‑A nodig heeft. Drie cellen per verpakking. Beschermingscircuit voorkomt overladen, diepontlading en kortsluiting.", "category": "Accessoires"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('18650-charger', 'nl', '{"name": "18650-batterijlader", "description": "Compacte 4-vaks lader voor 18650-cellen. Laadt veilig op tijdens de nacht. Automatische uitschakeling bij volle lading.", "category": "Accessoires"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-led', 'nl', '{"name": "3W Star LED (Reserve)", "description": "Warm-witte 3W vervangende LED-lampkop, voorbedraad met Wago-klaar kabels. Verwisselen zonder gereedschap. Past op zowel UFO- als Mushroom-modellen.", "category": "Accessoires"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-motor', 'nl', '{"name": "Gelijkstroommotor (Vervanging)", "description": "Drop-in vervangende gelijkstroommotor. Voorzien van Faston-connectoren — geen soldeerwerk, geen gereedschap nodig.", "category": "Accessoires"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-lever-switch', 'nl', '{"name": "3-Stands hendelschakelaar", "description": "Omhoog–Uit–Omlaag hendelbediening. Voorbedraad en klaar voor montage. De hendel die de paal laat stijgen, stoppen en intrekken.", "category": "Accessoires"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-push-switch', 'nl', '{"name": "Hoofdschakelaar (LED)", "description": "Ronde drukschakelaar met geïntegreerde LED-indicator. 2A 250V. Voorbedraad, klikvast.", "category": "Accessoires"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('spare-battery-holder', 'nl', '{"name": "3× 18650-batterijhouder", "description": "Beschermde batterijhouder met Wago-klaar uitgangskabels. Houdt drie 18650-cellen. Drop-in vervanging voor de Star‑A-basis.", "category": "Accessoires"}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('wago-terminals', 'nl', '{"name": "Wago 221-klemmen (10-stuks)", "description": "Gereedschapsloze steekverbindingen. Mix van 2-weg (221-412) en 3-weg (221-413) klemmen — dezelfde die in elk Star‑A-bouwpakket zitten.", "category": "Accessoires"}');
