INSERT INTO product_translations (product_id, lang, data) VALUES ('pre-assembled', 'pt', '{"name": "Star‑A — Fully Built", "description": "Fully assembled and tested. Load 3× 18650 batteries, flip the lever, watch jaws drop. Choose UFO or Mushroom — four colourways each. No build required.", "category": "Lamp", "shipsFrom": "Envio Dornori", "soldBy": "Dornori", "returns": "Devolução ou substituição em 30 dias", "specs": [{"title": "Características e Especificações", "rows": [["Altura (retraída)", "70 cm"], ["Altura (estendida)", "190 cm"], ["Fonte de luz", "LED branco quente 3W"], ["Alimentação", "3× baterias 18650 (não incluídas)"], ["Motor", "Motor DC com engrenagem, 3–6V"], ["Mecanismo de extensão", "Sistema telescópico de 3 seções com transmissão por engrenagem"]]}, {"title": "Materiais e Cuidados", "rows": [["Material do corpo", "PLA+ (impressão 3D)"], ["Acabamento", "Acentos de alumínio pintados a pó"], ["Material do abajur", "PC/ABS"], ["Limpeza", "Limpar com pano seco ou levemente húmido"], ["Resistência UV", "Moderada — evitar exposição prolongada à luz solar direta"]]}, {"title": "Detalhes do Produto", "rows": [["Modelo", "Star‑A"], ["Variantes", "UFO / Cogumelo, 4 combinações de cores cada"], ["Montagem necessária", "Não — completamente construído e testado"], ["Peso", "1,8 kg"], ["Dimensões da embalagem", "75 × 15 × 15 cm"]]}, {"title": "Garantia e Suporte", "rows": [["Período de garantia", "2 anos a partir da data de compra"], ["Suporte", "support@dornori.com"], ["Política de devolução", "Devolução ou substituição em 30 dias — sem perguntas"], ["Peças sobressalentes", "Disponíveis separadamente na loja"]]}]}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('star-a-kit', 'pt', '{"name": "Star‑A — Build-It Kit", "description": "Pre-printed parts and a complete electronics kit. Build in around 90 minutes with an adult. No 3D printer, no soldering, no component hunting. Step-by-step illustrated guide included. Choose UFO or Mushroom — four colourways each.", "category": "Kit", "shipsFrom": "Envio Dornori", "soldBy": "Dornori", "returns": "Devolução ou substituição em 30 dias", "specs": [{"title": "Conteúdo do Kit", "rows": [["Peças impressas", "Conjunto completo — base, tubos, caixa de engrenagens, cabeça"], ["Eletrónica", "Motor, interruptores, LED, porta-pilhas, feixe de cabos"], ["Conectores", "Terminais de alavanca Wago 221"], ["Manual", "Guia de montagem ilustrado passo a passo"]]}, {"title": "Informação de Montagem", "rows": [["Tempo de montagem", "~90 minutos"], ["Ferramentas necessárias", "Nenhuma"], ["Soldadura necessária", "Não"], ["Impressora 3D necessária", "Não"], ["Idade recomendada", "14+ (supervisão adulta para construtores mais jovens)"]]}, {"title": "Garantia e Suporte", "rows": [["Período de garantia", "2 anos a partir da data de compra"], ["Suporte", "support@dornori.com"], ["Política de devolução", "Devolução ou substituição em 30 dias"]]}]}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('complete-assembly-kit', 'pt', '{"name": "Complete Assembly Kit", "description": "Pre-printed parts and a complete electronics kit. Build in around 90 minutes with an adult. No 3D printer, no soldering. Step-by-step illustrated guide included.", "category": "Kit", "shipsFrom": "Envio Dornori", "soldBy": "Dornori", "returns": "Devolução ou substituição em 30 dias", "specs": [{"title": "Conteúdo do Kit", "rows": [["Peças impressas", "Conjunto completo — base, tubos, caixa de engrenagens, cabeça"], ["Eletrónica", "Motor, interruptores, LED, porta-pilhas, feixe de cabos"], ["Conectores", "Terminais de alavanca Wago 221"], ["Manual", "Guia de montagem ilustrado passo a passo"]]}, {"title": "Informação de Montagem", "rows": [["Tempo de montagem", "~90 minutos"], ["Ferramentas necessárias", "Nenhuma"], ["Soldadura necessária", "Não"], ["Impressora 3D necessária", "Não"], ["Idade recomendada", "14+ (supervisão adulta para construtores mais jovens)"]]}, {"title": "Garantia e Suporte", "rows": [["Período de garantia", "2 anos a partir da data de compra"], ["Suporte", "support@dornori.com"], ["Política de devolução", "Devolução ou substituição em 30 dias"]]}]}');
INSERT INTO product_translations (product_id, lang, data) VALUES ('electronics-bundle', 'pt', '{"name": "Electronics Bundle", "description": "All electronics pre-wired and ready to assemble — DC motor with Faston connectors, 3-position lever switch, main power switch, 3W LED lamp head, 3× 18650 battery holder, colour-coded wiring harness, and Wago lever terminals. No printed parts included.", "category": "Kit", "shipsFrom": "Envio Dornori", "soldBy": "Dornori", "returns": "Devolução ou substituição em 30 dias", "specs": [{"title": "Detalhes do Produto", "rows": [["Compatível com", "Star‑A (todas as variantes)"], ["Garantia", "1 ano"]]}, {"title": "Garantia e Suporte", "rows": [["Período de garantia", "1 ano"], ["Suporte", "support@dornori.com"], ["Política de devolução", "Devolução ou substituição em 30 dias"]]}]}');
