INSERT INTO reviews (product_id, data) VALUES ('ufo-spaceblue', '{"ratingBreakdown": {"5": 847, "4": 112, "3": 28, "2": 8, "1": 4}, "videos": [{"type": "youtube", "url": "https://www.youtube.com/embed/dQw4w9WgXcQ", "title": "UFO SpaceBlue unboxing & first impressions", "author": "TechLampReviews"}, {"type": "mp4", "url": "/assets/video/dornori_star-a_picknick.mp4", "title": "UFO SpaceBlue in action – picnic demo", "author": "Dornori"}, {"type": "youtube", "url": "https://www.youtube.com/embed/dQw4w9WgXcQ", "title": "Full review: is it worth it?", "author": "GadgetLab"}, {"type": "tiktok", "url": "https://www.tiktok.com/@dornori.info/video/7312345678901234567", "title": "Watch it rise! ✨ #dornori #ufo", "author": "@dornori.info"}, {"type": "youtube", "url": "https://www.youtube.com/embed/dQw4w9WgXcQ", "title": "SpaceBlue camping night shoot", "author": "OutdoorVibes"}], "reviews": [{"id": "r1", "author": "Marco V.", "location": "Amsterdam, NL", "date": "2025-03-12", "rating": 5, "verified": true, "title": "Absolutely stunning lamp – worth every cent", "body": "I''ve had the UFO SpaceBlue for three months now and it still blows people away every single time. The mechanism is buttery smooth and the SpaceBlue color is exactly as shown. Battery life is fantastic — three 18650s last a full weekend camping trip. Assembly was simple even without instructions, which says a lot.", "helpful": 47, "images": []}, {"id": "r2", "author": "Sarah K.", "location": "Berlin, DE", "date": "2025-02-28", "rating": 5, "verified": true, "title": "The reaction at my dinner party said everything", "body": "Guests literally stopped mid-conversation when I raised this lamp. It''s not just a light — it''s a conversation piece. The SpaceBlue finish is deep and beautiful. Shipping was fast and packaging was excellent.", "helpful": 39, "images": []}, {"id": "r3", "author": "Thomas B.", "location": "Ghent, BE", "date": "2025-01-15", "rating": 4, "verified": true, "title": "Great product, minor improvement possible", "body": "Really impressive engineering. The rising motion is satisfying every time. I give 4 stars only because I wish the carrying case were included. The lamp itself is perfect — solid, bright, and elegant. Already ordered a second one for a gift.", "helpful": 22, "images": [], "reply": {"author": "Dornori Team", "date": "2025-01-18", "body": "Thank you for the kind words and for the honest feedback! A carrying case is actually something we are working on — stay tuned. Enjoy your second lamp!"}}, {"id": "r4", "author": "Lena H.", "location": "Utrecht, NL", "date": "2025-04-02", "rating": 5, "verified": true, "title": "My kids are obsessed", "body": "We use this every evening on the back porch. My children love operating it and guests always ask where we got it. The color holds up after months of outdoor use. Customer service was also responsive when I had a question.", "helpful": 31, "images": []}, {"id": "r5", "author": "Pieter M.", "location": "Antwerp, BE", "date": "2025-03-29", "rating": 5, "verified": true, "title": "Pre-order was totally worth the wait", "body": "I was a bit nervous ordering a pre-order item but the communication was great throughout. The lamp arrived perfectly packaged and the SpaceBlue color is even more impressive in person. The mechanism feels premium — not a single creak or wobble.", "helpful": 18, "images": [], "reply": {"author": "Dornori Team", "date": "2025-04-05", "body": "We really appreciate your patience and kind words. Pre-orders are always a leap of faith and we take that seriously. Glad it arrived in perfect shape — enjoy it!"}}, {"id": "r6", "author": "Kevin D.", "location": "Rotterdam, NL", "date": "2025-04-18", "rating": 2, "verified": true, "title": "Motor stopped working after 2 weeks", "body": "Really loved the concept but unfortunately the motor mechanism stopped responding after about two weeks of use. Disappointing for the price point.", "helpful": 9, "images": [], "reply": {"author": "Dornori Team", "date": "2025-04-20", "body": "We are sorry to hear this, Kevin — that is definitely not the experience we want you to have. Please reach out to us directly at support@dornori.com and we will make it right straight away. Our motors carry a 2-year warranty and we will sort this for you."}}]}');
